-- Catalogue corrections after the 2026-09-30 data audit: precise labels (asking rent, shares of district area), one terminology
-- ("wskaźnik jakości życia"), units that match the loaded rows, and an English and Polish description for every metric.
-- Supersedes the labels, descriptions and units in 0002; apply it after 0002 (and 0004). Safe to re-run. Polish text needs a native-speaker review.
update krakow.metric_definitions m
   set label_en = v.label_en, label_pl = v.label_pl, description_en = v.description_en, description_pl = v.description_pl, unit = v.unit
  from (values
  ('transit_stops_total', 'Public transport stops', 'Przystanki komunikacji miejskiej', 'Distinct public transport stops (bus, tram, rail, metro) inside the district, from the timetable feeds; platforms of one stop count once.', 'Liczba odrębnych przystanków komunikacji miejskiej (autobus, tramwaj, kolej, metro) w dzielnicy, według danych rozkładowych; perony jednego przystanku liczone są raz.', 'stops'),
  ('transit_stops_bus', 'Bus stops', 'Przystanki autobusowe', 'Distinct stops served by bus routes.', 'Odrębne przystanki obsługiwane przez linie autobusowe.', 'stops'),
  ('transit_stops_tram', 'Tram stops', 'Przystanki tramwajowe', 'Distinct stops served by tram routes.', 'Odrębne przystanki obsługiwane przez linie tramwajowe.', 'stops'),
  ('transit_stops_rail_metro', 'Rail and metro stations', 'Stacje kolejowe i metra', 'Rail and metro stations in the timetable feed (Warsaw: metro, SKM, rail, WKD). Not available for Kraków, whose feeds contain no rail.', 'Stacje kolejowe i metra z danych rozkładowych (Warszawa: metro, SKM, kolej, WKD). Brak dla Krakowa, którego dane nie zawierają kolei.', 'stations'),
  ('transit_routes_count', 'Routes serving the district', 'Linie obsługujące dzielnicę', 'Distinct route numbers with at least one stop in the district.', 'Liczba odrębnych linii mających co najmniej jeden przystanek w dzielnicy.', 'routes'),
  ('transit_departures_weekday', 'Weekday departures', 'Odjazdy w dzień roboczy', 'Scheduled departures from the district''s stops on a typical weekday (Tuesday 6 October 2026).', 'Rozkładowe odjazdy z przystanków dzielnicy w typowy dzień roboczy (wtorek 6 października 2026).', 'departures/day'),
  ('transit_night_departures', 'Night departures', 'Odjazdy nocne', 'Scheduled departures between 23:00 and 04:59 on that weekday.', 'Rozkładowe odjazdy między 23:00 a 4:59 w tym dniu roboczym.', 'departures/night'),
  ('airport_distance_km', 'Distance to the airport', 'Odległość od lotniska', 'Straight-line distance from the district centre to the main airport (Kraków-Balice, Warsaw Chopin); not a travel time.', 'Odległość w linii prostej od środka dzielnicy do głównego lotniska (Kraków-Balice, Lotnisko Chopina); nie jest to czas dojazdu.', 'km'),
  ('population_total', 'Population', 'Liczba ludności', 'Resident population at 31 December 2024 (Warsaw, statistical office). Not available for Kraków.', 'Liczba ludności na 31 grudnia 2024 (Warszawa, urząd statystyczny). Brak dla Krakowa.', 'people'),
  ('residents_registered', 'Registered permanent residents', 'Zameldowani na pobyt stały', 'People registered for permanent residence. Not the same as total population.', 'Osoby zameldowane na pobyt stały. To nie jest liczba ludności ogółem.', 'people'),
  ('population_density', 'Population density', 'Gęstość zaludnienia', 'People per km² of district area. Warsaw: official figure. Kraków: registered residents over district area, so an underestimate.', 'Liczba osób na km² powierzchni dzielnicy. Warszawa: dane oficjalne. Kraków: zameldowani w przeliczeniu na powierzchnię, więc wartość zaniżona.', 'people/km²'),
  ('age_mean', 'Average age', 'Średni wiek', 'Mean age of residents. Warsaw: estimated from 5-year age bands. Kraków: from the year of birth of registered residents.', 'Średni wiek mieszkańców. Warszawa: szacunek z grup wiekowych co 5 lat. Kraków: z roku urodzenia osób zameldowanych.', 'years'),
  ('share_age_65_plus', 'Residents aged 65 or older', 'Mieszkańcy w wieku 65+', 'Share of residents aged 65 or older.', 'Odsetek mieszkańców w wieku 65 lat i więcej.', '%'),
  ('share_female', 'Share of women', 'Udział kobiet', 'Share of women among residents.', 'Odsetek kobiet wśród mieszkańców.', '%'),
  ('amenity_schools', 'Schools', 'Szkoły', 'Schools mapped in OpenStreetMap inside the district; counts reflect how completely volunteers have mapped them.', 'Szkoły zmapowane w OpenStreetMap w granicach dzielnicy; liczba zależy od kompletności mapowania.', 'count'),
  ('amenity_hospitals_clinics', 'Hospitals and clinics', 'Szpitale i przychodnie', 'Hospitals and clinics mapped in OpenStreetMap inside the district.', 'Szpitale i przychodnie zmapowane w OpenStreetMap w granicach dzielnicy.', 'count'),
  ('amenity_parks_share', 'Park share of district area', 'Udział powierzchni parków', 'Share of the district area covered by parks (OpenStreetMap leisure=park); forests and cemeteries are not counted.', 'Udział powierzchni dzielnicy zajmowany przez parki (OpenStreetMap leisure=park); lasy i cmentarze nie są liczone.', '% of district'),
  ('amenity_supermarkets', 'Supermarkets', 'Supermarkety', 'Supermarkets mapped in OpenStreetMap inside the district.', 'Supermarkety zmapowane w OpenStreetMap w granicach dzielnicy.', 'count'),
  ('amenity_malls', 'Shopping centres', 'Centra handlowe', 'Shopping centres mapped in OpenStreetMap inside the district.', 'Centra handlowe zmapowane w OpenStreetMap w granicach dzielnicy.', 'count'),
  ('amenity_gyms', 'Gyms and fitness clubs', 'Siłownie i kluby fitness', 'Gyms and fitness clubs mapped in OpenStreetMap inside the district.', 'Siłownie i kluby fitness zmapowane w OpenStreetMap w granicach dzielnicy.', 'count'),
  ('amenity_parking', 'Car parks', 'Parkingi', 'Car parks and parking structures mapped in OpenStreetMap; shown for information and not scored.', 'Parkingi zmapowane w OpenStreetMap; pokazywane informacyjnie, bez wpływu na wskaźniki.', 'count'),
  ('air_pm10_mean', 'PM10 (annual mean)', 'Pył PM10 (średnia roczna)', 'Annual mean PM10 over the 12 months to August 2026, interpolated between GIOŚ stations; not address-level exposure.', 'Średnie roczne stężenie pyłu PM10 w 12 miesiącach do sierpnia 2026, interpolowane między stacjami GIOŚ; nie jest to narażenie na poziomie adresu.', 'µg/m³'),
  ('air_pm25_mean', 'PM2.5 (annual mean)', 'Pył PM2,5 (średnia roczna)', 'Annual mean PM2.5 over the 12 months to August 2026, interpolated between GIOŚ stations; few stations measure it, so districts differ little.', 'Średnie roczne stężenie pyłu PM2,5 w 12 miesiącach do sierpnia 2026, interpolowane między stacjami GIOŚ; mierzy go niewiele stacji, więc różnice między dzielnicami są małe.', 'µg/m³'),
  ('air_no2_mean', 'NO₂ (annual mean)', 'Dwutlenek azotu NO₂ (średnia roczna)', 'Annual mean nitrogen dioxide over the 12 months to August 2026, interpolated between GIOŚ stations; not address-level exposure.', 'Średnie roczne stężenie dwutlenku azotu w 12 miesiącach do sierpnia 2026, interpolowane między stacjami GIOŚ; nie jest to narażenie na poziomie adresu.', 'µg/m³'),
  ('air_quality_index', 'Air quality index (latest)', 'Indeks jakości powietrza (ostatni)', 'GIOŚ index from 0 (very good) to 5 (very bad), latest reading, interpolated between stations.', 'Indeks GIOŚ od 0 (bardzo dobry) do 5 (bardzo zły), ostatni odczyt, interpolowany między stacjami.', 'index 0-5'),
  ('tree_cover_share', 'Tree cover', 'Pokrycie drzewami', 'Share of the district area under tree canopy (Copernicus Tree Cover Density 2024, 10 m); includes gardens and street trees.', 'Udział powierzchni dzielnicy pokryty koronami drzew (Copernicus Tree Cover Density 2024, 10 m); obejmuje ogrody i drzewa przyuliczne.', '% of district'),
  ('green_space_share', 'Green space', 'Tereny zielone', 'Share of the district area classified as green urban areas or forest (Copernicus Urban Atlas 2018).', 'Udział powierzchni dzielnicy sklasyfikowany jako tereny zieleni miejskiej lub las (Copernicus Urban Atlas 2018).', '% of district'),
  ('heat_exposure_index', 'Summer heat exposure', 'Ekspozycja na upał latem', 'Proxy from low tree cover and low green space; higher means hotter. Compares districts of one city only (0-100).', 'Wskaźnik zastępczy z niskiego pokrycia drzewami i małej ilości terenów zielonych; wyższa wartość oznacza więcej upału. Porównuje tylko dzielnice jednego miasta (0-100).', 'index'),
  ('noise_share_above_55db', 'District area above 55 dB', 'Udział powierzchni powyżej 55 dB', 'Share of the district area with a noise level of 55 dB Lden or more in the 2022 strategic noise map (Warsaw: road, rail, tram, air and industry; Kraków: road, rail and industry).', 'Udział powierzchni dzielnicy z poziomem hałasu co najmniej 55 dB Lden na strategicznej mapie hałasu 2022 (Warszawa: drogi, kolej, tramwaje, lotnisko i przemysł; Kraków: drogi, kolej i przemysł).', '% of district'),
  ('night_noise_estimate', 'Night noise (estimate)', 'Hałas nocny (szacunek)', 'Proxy from nightlife density and the share of the district above 55 dB; higher means louder. Compares districts of one city only (0-100).', 'Wskaźnik zastępczy z gęstości lokali nocnych i udziału powierzchni powyżej 55 dB; wyższa wartość oznacza głośniej. Porównuje tylko dzielnice jednego miasta (0-100).', 'index'),
  ('nightlife_density', 'Bars and clubs', 'Bary i kluby', 'Bars, pubs and nightclubs per km² (OpenStreetMap).', 'Bary, puby i kluby nocne na km² (OpenStreetMap).', 'per km²'),
  ('busyness_index', 'Busyness', 'Ruch i tłok', 'Proxy from the density of stops, departures, shops and nightlife; higher means busier. Compares districts of one city only (0-100).', 'Wskaźnik zastępczy z gęstości przystanków, odjazdów, sklepów i lokali nocnych; wyższa wartość oznacza większy ruch i tłok. Porównuje tylko dzielnice jednego miasta (0-100).', 'index'),
  ('walkability_index', 'Walkability', 'Dostępność usług pieszo', 'Proxy from the density of supermarkets, schools, clinics and stops and the park share; higher means more daily needs close by. Compares districts of one city only (0-100).', 'Wskaźnik zastępczy z gęstości supermarketów, szkół, przychodni i przystanków oraz udziału parków; wyższa wartość oznacza więcej usług codziennych w pobliżu. Porównuje tylko dzielnice jednego miasta (0-100).', 'index'),
  ('family_friendliness_index', 'Family friendliness', 'Przyjazność dla rodzin', 'Proxy from school density, green space, tree cover, low noise and few pedestrian and cyclist casualties. Compares districts of one city only (0-100).', 'Wskaźnik zastępczy z gęstości szkół, terenów zielonych, pokrycia drzewami, niskiego hałasu i małej liczby poszkodowanych pieszych i rowerzystów. Porównuje tylko dzielnice jednego miasta (0-100).', 'index'),
  ('sale_price_median_m2', 'Median sale price per m²', 'Mediana ceny sprzedaży za m²', 'Median gross price per m² of free-market residential sales in the official RCN register, 24 months to September 2026.', 'Mediana ceny brutto za m² mieszkań sprzedanych na wolnym rynku w oficjalnym Rejestrze Cen Nieruchomości, 24 miesiące do września 2026.', 'PLN/m²'),
  ('sale_transactions_count', 'Sale transactions counted', 'Liczba uwzględnionych transakcji', 'Number of transactions behind the median sale price.', 'Liczba transakcji, z których obliczono medianę ceny sprzedaży.', 'count'),
  ('rent_price_median_m2', 'Median asking rent per m²', 'Mediana ofertowego czynszu za m²', 'Median asking rent per m² (without the service charge) from Otodom and OLX listings, one snapshot in September 2026; not signed contracts.', 'Mediana ofertowego czynszu za m² (bez opłat dodatkowych) z ogłoszeń Otodom i OLX, jednorazowy zrzut z września 2026; nie są to zawarte umowy.', 'PLN/m²'),
  ('rent_listings_count', 'Rent listings counted', 'Liczba uwzględnionych ofert najmu', 'Number of rent listings behind the median asking rent, after removing cross-postings.', 'Liczba ofert najmu, z których obliczono medianę czynszu ofertowego, po usunięciu duplikatów z obu portali.', 'count'),
  ('crimes_per_10k', 'Recorded crimes per 10,000 residents', 'Przestępstwa stwierdzone na 10 000 mieszkańców', 'Crimes recorded by the police per 10,000 residents in 2024 (Warsaw only). Higher in districts with many visitors and commuters; not a measure of risk.', 'Przestępstwa stwierdzone przez policję na 10 000 mieszkańców w 2024 r. (tylko Warszawa). Wyższe w dzielnicach z wieloma odwiedzającymi i dojeżdżającymi; nie jest miarą ryzyka.', 'per 10,000'),
  ('crime_detection_rate', 'Offender detection rate', 'Wskaźnik wykrywalności sprawców', 'Share of recorded crimes in 2024 with a detected offender (Warsaw only).', 'Odsetek przestępstw stwierdzonych w 2024 r., w których wykryto sprawcę (tylko Warszawa).', '%'),
  ('road_accidents_per_km', 'Road accidents per km of road', 'Wypadki drogowe na km dróg', 'Road accidents with injury or death per km of road per year, mean of 2022-2024 (police SEWiK data).', 'Wypadki drogowe z rannymi lub zabitymi na km dróg rocznie, średnia z lat 2022-2024 (policyjne dane SEWiK).', 'per km per year'),
  ('road_ped_cyc_casualties_per_km', 'Pedestrian and cyclist casualties per km', 'Poszkodowani piesi i rowerzyści na km', 'Injured or killed pedestrians and cyclists per km of road per year, mean of 2022-2024 (police SEWiK data).', 'Ranni lub zabici piesi i rowerzyści na km dróg rocznie, średnia z lat 2022-2024 (policyjne dane SEWiK).', 'per km per year'),
  ('lit_street_share', 'Streets tagged as lit', 'Ulice oznaczone jako oświetlone', 'Share of road length tagged as lit in OpenStreetMap. Untagged roads may still be lit, so this is a weak signal.', 'Udział długości dróg oznaczonych w OpenStreetMap jako oświetlone. Drogi bez oznaczenia mogą być oświetlone, więc to słaby sygnał.', '%'),
  ('emergency_services_distance_km', 'Average distance to police, fire station and hospital', 'Średnia odległość do policji, straży pożarnej i szpitala', 'Mean straight-line distance from the district centre to the nearest police station, fire station and hospital (OpenStreetMap); not a response time.', 'Średnia odległość w linii prostej od środka dzielnicy do najbliższej komendy policji, remizy straży pożarnej i szpitala (OpenStreetMap); nie jest czasem dojazdu.', 'km'),
  ('safety_index', 'Safety index (composite)', 'Wskaźnik bezpieczeństwa (złożony)', 'Composite of the road safety, street lighting, emergency-service distance and (Warsaw only) recorded crime metrics; higher is better. Compares districts of one city only (0-100). Not a statement that an area is safe or unsafe.', 'Wskaźnik złożony z mierników bezpieczeństwa drogowego, oświetlenia ulic, odległości do służb ratunkowych i (tylko Warszawa) przestępstw stwierdzonych; wyższa wartość jest lepsza. Porównuje tylko dzielnice jednego miasta (0-100). Nie jest stwierdzeniem, że okolica jest bezpieczna lub niebezpieczna.', 'index'),
  ('livability_score_default', 'Livability score (default weights)', 'Wskaźnik jakości życia (wagi domyślne)', 'Default livability score from 0 to 100: mean of percentile ranks of all directional metrics, each category counting equally. Compares districts of one city only; rent and sale price count against a district.', 'Domyślny wskaźnik jakości życia od 0 do 100: średnia rang percentylowych wszystkich mierników o określonym kierunku, przy równej wadze każdej kategorii. Porównuje tylko dzielnice jednego miasta; czynsz i cena sprzedaży obniżają wynik dzielnicy.', 'score 0-100')
  ) as v(metric_key, label_en, label_pl, description_en, description_pl, unit)
 where m.metric_key = v.metric_key;
